  liu("I was born in Kyiv.", "Прослухайте. Де народилася людина?", ["У Києві", "У Львові", "В Одесі"], "Kyiv."),
  liu("I grew up in a small town.", "Прослухайте. Де виросла людина?", ["У маленькому місті", "У великому місті", "У селі"], "A small town."),
  liu("My native language is Ukrainian.", "Прослухайте. Яка рідна мова?", ["Українська", "Польська", "Англійська"], "Ukrainian."),
  fb("My ___ is Lviv.", ["hometown", "native", "originally"], "Hometown."),
  fb("I ___ born in Kyiv.", ["was", "am", "is"], "I was born."),
  fb("I'm ___ from Poland.", ["originally", "native", "grew"], "Originally from."),
  mc("Як сказати «Я виріс у маленькому місті»?", ["I grew up in a small town.", "I grow up in small town.", "I am grown in a town small."], "I grew up."),
  bs("Я народився у Києві.", ["I", "was", "born", "in", "Kyiv"], ["am", "were"], "I was born in Kyiv."),
